class Leaderboard {
  private final Map<Integer, Integer> scoreByPlayerId = new HashMap<>();

  private final TreeMap<Integer, Set<Integer>> playerIdsByScore =
      new TreeMap<>(Comparator.<Integer>reverseOrder());

  public Leaderboard() {}

  public void addScore(int playerId, int score) {
    if (scoreByPlayerId.containsKey(playerId)) {
      score += resetAndGetOldScore(playerId);
    }

    scoreByPlayerId.put(playerId, score);
    playerIdsByScore.computeIfAbsent(score, (ignored) -> new HashSet<>()).add(playerId);
  }

  public int top(int K) {
    int finalScore = 0;
    for (int score : playerIdsByScore.keySet()) {
      int playersCount = playerIdsByScore.get(score).size();
      while (playersCount-- > 0 && K-- > 0) {
        finalScore += score;
      }

      if (K == 0) {
        break;
      }
    }
    return finalScore;
  }

  private int resetAndGetOldScore(int playerId) {
    int oldScore = scoreByPlayerId.get(playerId);

    if (playerIdsByScore.get(oldScore).size() == 1) {
      playerIdsByScore.remove(oldScore);
    } else {
      playerIdsByScore.get(oldScore).remove(playerId);
    }

    scoreByPlayerId.remove(playerId);
    return oldScore;
  }

  public void reset(int playerId) {
    resetAndGetOldScore(playerId);
  }
}

